CREATE     PROCEDURE [synapse_fo].[usp_Insert_VENDTRANS]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:03
	Description: Insert stored procedure for VENDTRANS from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[VENDTRANS]
	(
		[ACCOUNTINGEVENT],
		[ACCOUNTNUM],
		[AMOUNTCUR],
		[AMOUNTMST],
		[APPROVED],
		[APPROVEDDATE],
		[APPROVER],
		[ARRIVAL],
		[ARRIVALACCOUNTID],
		[BANKCENTRALBANKPURPOSECODE],
		[BANKCENTRALBANKPURPOSETEXT],
		[BANKLCIMPORTLINE],
		[BANKREMITTANCEFILEID],
		[CANCEL],
		[CASHDISCBASEDATE],
		[CASHDISCCODE],
		[CLOSED],
		[COMPANYBANKACCOUNTID],
		[CORRECT],
		[CREATEDBY],
		[CREATEDDATETIME],
		[CREATEDTRANSACTIONID],
		[CURRENCYCODE],
		[DATAAREAID],
		[DataLakeModified_DateTime],
		[DEFAULTDIMENSION],
		[DOCUMENTDATE],
		[DOCUMENTNUM],
		[DUEDATE],
		[EUROTRIANGULATION],
		[EXCHADJUSTMENT],
		[EXCHADJUSTMENTREPORTING],
		[EXCHRATE],
		[EXCHRATESECOND],
		--[FileName],
		[FIXEDEXCHRATE],
		[INVOICE],
		[INVOICEPROJECT],
		[INVOICERELEASEDATE],
		--[INVOICERELEASEDATETZID],
		[JOURNALNUM],
		[LASTEXCHADJ],
		[LASTEXCHADJRATE],
		[LASTEXCHADJRATEREPORTING],
		[LASTEXCHADJVOUCHER],
		[LastProcessedChange_DateTime],
		[LASTSETTLEACCOUNTNUM],
		[LASTSETTLECOMPANY],
		[LASTSETTLEDATE],
		[LASTSETTLEVOUCHER],
		--[LSN],
		[MODIFIEDBY],
		[MODIFIEDDATETIME],
		[MODIFIEDTRANSACTIONID],
		[OFFSETRECID],
		[PARTITION],
		[PAYMID],
		[PAYMMODE],
		[PAYMREFERENCE],
		[PAYMSPEC],
		[PAYMTERMID],
		[POSTINGPROFILE],
		[POSTINGPROFILEAPPROVE],
		[POSTINGPROFILECANCEL],
		[POSTINGPROFILECLOSE],
		[POSTINGPROFILEREOPEN],
		[PREPAYMENT],
		[PROMISSORYNOTEID],
		[PROMISSORYNOTESEQNUM],
		[PROMISSORYNOTESTATUS],
		[PSNJOURNALIZINGDEFINITION],
		[PSNPURCHASINGCARDTYPE],
		[RBOVENDTRANS],
		[REASONREFRECID],
		[RECID],
		[RECVERSION],
		[RELEASEDATECOMMENT],
		[REMITTANCEADDRESS],
		[REMITTANCELOCATION],
		[REPORTINGCURRENCYAMOUNT],
		[REPORTINGCURRENCYCROSSRATE],
		[REPORTINGCURRENCYEXCHRATE],
		[REPORTINGCURRENCYEXCHRATESECONDARY],
		[REPORTINGEXCHADJUSTMENTREALIZED],
		[REPORTINGEXCHADJUSTMENTUNREALIZED],
		[SETTLEAMOUNTCUR],
		[SETTLEAMOUNTMST],
		[SETTLEAMOUNTREPORTING],
		[SETTLEMENT],
		[SETTLETAX1099AMOUNT],
		[SETTLETAX1099STATEAMOUNT],
		--[SKS_BR_CLEAREDDATE],
		[SUMMARYACCOUNTID],
		--[SysRowId],
		[TAX1099AMOUNT],
		[TAX1099DATE],
		[TAX1099FIELDS],
		[TAX1099NUM],
		[TAX1099RECID],
		[TAX1099STATE],
		[TAX1099STATEAMOUNT],
		[TAXINVOICEPURCHID],
		[THIRDPARTYBANKACCOUNTID],
		[TRANSDATE],
		[TRANSTYPE],
		[TXT],
		[VENDEXCHADJUSTMENTREALIZED],
		[VENDEXCHADJUSTMENTUNREALIZED],
		[VENDORVATDATE],
		[VENDPAYMENTGROUP],
		[VOUCHER]
	)
	SELECT 
		stg.[ACCOUNTINGEVENT],
		stg.[ACCOUNTNUM],
		stg.[AMOUNTCUR],
		stg.[AMOUNTMST],
		stg.[APPROVED],
		stg.[APPROVEDDATE],
		stg.[APPROVER],
		stg.[ARRIVAL],
		stg.[ARRIVALACCOUNTID],
		stg.[BANKCENTRALBANKPURPOSECODE],
		stg.[BANKCENTRALBANKPURPOSETEXT],
		stg.[BANKLCIMPORTLINE],
		stg.[BANKREMITTANCEFILEID],
		stg.[CANCEL],
		stg.[CASHDISCBASEDATE],
		stg.[CASHDISCCODE],
		stg.[CLOSED],
		stg.[COMPANYBANKACCOUNTID],
		stg.[CORRECT],
		stg.[CREATEDBY],
		stg.[CREATEDDATETIME],
		stg.[CREATEDTRANSACTIONID],
		stg.[CURRENCYCODE],
		stg.[DATAAREAID],
		stg.[DataLakeModified_DateTime],
		stg.[DEFAULTDIMENSION],
		stg.[DOCUMENTDATE],
		stg.[DOCUMENTNUM],
		stg.[DUEDATE],
		stg.[EUROTRIANGULATION],
		stg.[EXCHADJUSTMENT],
		stg.[EXCHADJUSTMENTREPORTING],
		stg.[EXCHRATE],
		stg.[EXCHRATESECOND],
		--stg.--[FileName],
		stg.[FIXEDEXCHRATE],
		stg.[INVOICE],
		stg.[INVOICEPROJECT],
		stg.[INVOICERELEASEDATE],
		--stg.[INVOICERELEASEDATETZID],
		stg.[JOURNALNUM],
		stg.[LASTEXCHADJ],
		stg.[LASTEXCHADJRATE],
		stg.[LASTEXCHADJRATEREPORTING],
		stg.[LASTEXCHADJVOUCHER],
		stg.[LastProcessedChange_DateTime],
		stg.[LASTSETTLEACCOUNTNUM],
		stg.[LASTSETTLECOMPANY],
		stg.[LASTSETTLEDATE],
		stg.[LASTSETTLEVOUCHER],
		--stg.--[LSN],
		stg.[MODIFIEDBY],
		stg.[MODIFIEDDATETIME],
		stg.[MODIFIEDTRANSACTIONID],
		stg.[OFFSETRECID],
		stg.[PARTITION],
		stg.[PAYMID],
		stg.[PAYMMODE],
		stg.[PAYMREFERENCE],
		stg.[PAYMSPEC],
		stg.[PAYMTERMID],
		stg.[POSTINGPROFILE],
		stg.[POSTINGPROFILEAPPROVE],
		stg.[POSTINGPROFILECANCEL],
		stg.[POSTINGPROFILECLOSE],
		stg.[POSTINGPROFILEREOPEN],
		stg.[PREPAYMENT],
		stg.[PROMISSORYNOTEID],
		stg.[PROMISSORYNOTESEQNUM],
		stg.[PROMISSORYNOTESTATUS],
		stg.[PSNJOURNALIZINGDEFINITION],
		stg.[PSNPURCHASINGCARDTYPE],
		stg.[RBOVENDTRANS],
		stg.[REASONREFRECID],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[RELEASEDATECOMMENT],
		stg.[REMITTANCEADDRESS],
		stg.[REMITTANCELOCATION],
		stg.[REPORTINGCURRENCYAMOUNT],
		stg.[REPORTINGCURRENCYCROSSRATE],
		stg.[REPORTINGCURRENCYEXCHRATE],
		stg.[REPORTINGCURRENCYEXCHRATESECONDARY],
		stg.[REPORTINGEXCHADJUSTMENTREALIZED],
		stg.[REPORTINGEXCHADJUSTMENTUNREALIZED],
		stg.[SETTLEAMOUNTCUR],
		stg.[SETTLEAMOUNTMST],
		stg.[SETTLEAMOUNTREPORTING],
		stg.[SETTLEMENT],
		stg.[SETTLETAX1099AMOUNT],
		stg.[SETTLETAX1099STATEAMOUNT],
		--stg.[SKS_BR_CLEAREDDATE],
		stg.[SUMMARYACCOUNTID],
		--stg.--[SysRowId],
		stg.[TAX1099AMOUNT],
		stg.[TAX1099DATE],
		stg.[TAX1099FIELDS],
		stg.[TAX1099NUM],
		stg.[TAX1099RECID],
		stg.[TAX1099STATE],
		stg.[TAX1099STATEAMOUNT],
		stg.[TAXINVOICEPURCHID],
		stg.[THIRDPARTYBANKACCOUNTID],
		stg.[TRANSDATE],
		stg.[TRANSTYPE],
		stg.[TXT],
		stg.[VENDEXCHADJUSTMENTREALIZED],
		stg.[VENDEXCHADJUSTMENTUNREALIZED],
		stg.[VENDORVATDATE],
		stg.[VENDPAYMENTGROUP],
		stg.[VOUCHER]	
	FROM [staging_fo].[VENDTRANS] stg
		LEFT JOIN [synapse_fo].[VENDTRANS] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL
END
